CREATE TABLE "Sanction" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "subjectKind" TEXT NOT NULL,
  "staffId" TEXT,
  "clientId" TEXT,
  "state" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "startDate" TEXT NOT NULL CHECK ("startDate" IS NULL OR "startDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "endDate" TEXT CHECK ("endDate" IS NULL OR "endDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "violationId" TEXT,
  "setByUserId" TEXT NOT NULL,
  "setAt" TEXT NOT NULL,
  "liftedAt" TEXT,
  "liftedByUserId" TEXT,
  "liftReason" TEXT,
  "displayName" TEXT NOT NULL,
  "displayNumber" TEXT,
  "nameKey" TEXT,
  "nameLatinKey" TEXT,
  "birthDate" TEXT CHECK ("birthDate" IS NULL OR "birthDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "phoneKeys" TEXT,
  "nationalIdNumber" TEXT,
  "extraKeys" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  FOREIGN KEY ("staffId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("clientId") REFERENCES "Client" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("violationId") REFERENCES "Violation" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("setByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("liftedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK ("state" IN ('SUSPENDED','PENALISED')),
  CHECK (("subjectKind" = 'CLIENT' AND "clientId" IS NOT NULL AND "staffId" IS NULL) OR ("subjectKind" IN ('WORKER','EMPLOYEE') AND "staffId" IS NOT NULL AND "clientId" IS NULL))
) STRICT;
CREATE INDEX "Sanction_staffId_idx" ON "Sanction" ("staffId");
CREATE INDEX "Sanction_clientId_idx" ON "Sanction" ("clientId");
CREATE INDEX "Sanction_liftedAt_startDate_endDate_idx" ON "Sanction" ("liftedAt", "startDate", "endDate");
CREATE INDEX "Sanction_nameKey_idx" ON "Sanction" ("nameKey");
CREATE INDEX "Sanction_nationalIdNumber_idx" ON "Sanction" ("nationalIdNumber");

