CREATE TABLE "Visit" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "numberSeq" INTEGER NOT NULL,
  "numberYear" INTEGER NOT NULL,
  "number" TEXT NOT NULL,
  "fileId" TEXT NOT NULL,
  "fileSlotId" TEXT,
  "origin" TEXT NOT NULL,
  "sourceVisitId" TEXT,
  "slotDate" TEXT CHECK ("slotDate" IS NULL OR "slotDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "visitDate" TEXT NOT NULL CHECK ("visitDate" IS NULL OR "visitDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "plannedStartTime" TEXT NOT NULL CHECK ("plannedStartTime" IS NULL OR "plannedStartTime" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "plannedDurationMin" INTEGER NOT NULL,
  "workersNeeded" INTEGER NOT NULL,
  "zoneId" TEXT,
  "supervisorEmployeeId" TEXT,
  "teamId" TEXT,
  "vehicleId" TEXT,
  "transportMode" TEXT,
  "dayOrder" INTEGER,
  "isManuallyEdited" INTEGER NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL,
  "statusChangedAt" TEXT NOT NULL,
  "statusChangedByUserId" TEXT,
  "statusReason" TEXT,
  "statusNote" TEXT,
  "rescheduledToVisitId" TEXT,
  "billable" INTEGER NOT NULL DEFAULT 0,
  "clientAtFault" INTEGER,
  "orderPrintedAt" TEXT,
  "orderPrintedByUserId" TEXT,
  "orderPrintCount" INTEGER NOT NULL DEFAULT 0,
  "checklistFrozenAt" TEXT,
  "planChangedAt" TEXT,
  "orderReleasedAt" TEXT,
  "orderReleasedByUserId" TEXT,
  "arrivalReportedAt" TEXT,
  "arrivalReportedVia" TEXT,
  "arrivalReportedByUserId" TEXT,
  "clientInformedAt" TEXT,
  "actionTaken" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("fileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("fileSlotId") REFERENCES "FileSlot" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("sourceVisitId") REFERENCES "Visit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("rescheduledToVisitId") REFERENCES "Visit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("zoneId") REFERENCES "Zone" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("supervisorEmployeeId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("teamId") REFERENCES "Team" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("vehicleId") REFERENCES "Vehicle" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("statusChangedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("orderPrintedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("orderReleasedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("arrivalReportedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  UNIQUE ("numberYear", "numberSeq"),
  CHECK ("status" IN ('CONFIRMED','AWAITING_CONFIRMATION','IN_PROGRESS','DONE','POSTPONED','PROBLEM','CANCELLED'))
) STRICT;
CREATE INDEX "Visit_visitDate_status_idx" ON "Visit" ("visitDate", "status");
CREATE INDEX "Visit_fileId_visitDate_idx" ON "Visit" ("fileId", "visitDate");
CREATE INDEX "Visit_status_idx" ON "Visit" ("status");
CREATE INDEX "Visit_zoneId_visitDate_idx" ON "Visit" ("zoneId", "visitDate");
CREATE INDEX "Visit_supervisorEmployeeId_visitDate_idx" ON "Visit" ("supervisorEmployeeId", "visitDate");
CREATE INDEX "Visit_teamId_visitDate_idx" ON "Visit" ("teamId", "visitDate");
CREATE UNIQUE INDEX "Visit_slot_day" ON "Visit" ("fileId", "fileSlotId", "slotDate") WHERE "fileSlotId" IS NOT NULL AND "origin" IN ('CONTRACT','ON_DEMAND') AND "statusReason" IS NOT 'PROGRAMME_CHANGED';
CREATE UNIQUE INDEX "Visit_day" ON "Visit" ("fileId", "slotDate") WHERE "fileSlotId" IS NULL AND "origin" = 'ON_DEMAND' AND "statusReason" IS NOT 'PROGRAMME_CHANGED';

CREATE TABLE "VisitWorker" (
