  "workStartTime" TEXT CHECK ("workStartTime" IS NULL OR "workStartTime" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "workEndTime" TEXT CHECK ("workEndTime" IS NULL OR "workEndTime" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "leftTime" TEXT CHECK ("leftTime" IS NULL OR "leftTime" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "presenceProof" TEXT,
  "lateMin" INTEGER,
  "lateReason" TEXT,
  "workedMin" INTEGER,
  "attendanceSource" TEXT,
  "enteredAt" TEXT,
  "enteredByUserId" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("visitId") REFERENCES "Visit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("workerId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("replacesVisitWorkerId") REFERENCES "VisitWorker" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("absenceId") REFERENCES "WorkerAbsence" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("replacedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("enteredByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK ("seatStatus" <> 'ABSENT' OR "absenceId" IS NOT NULL)
) STRICT;
