CREATE TABLE "WorkerAbsence" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "workerId" TEXT NOT NULL,
  "startDate" TEXT NOT NULL CHECK ("startDate" IS NULL OR "startDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "endDate" TEXT NOT NULL CHECK ("endDate" IS NULL OR "endDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "type" TEXT NOT NULL,
  "startTime" TEXT CHECK ("startTime" IS NULL OR "startTime" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "endTime" TEXT CHECK ("endTime" IS NULL OR "endTime" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "absenceMin" INTEGER NOT NULL,
  "category" TEXT NOT NULL,
  "leaveType" TEXT,
  "days" INTEGER,
  "splitGroupId" TEXT,
  "paid" INTEGER NOT NULL DEFAULT 0,
  "justified" INTEGER NOT NULL DEFAULT 0,
  "plannedAhead" INTEGER NOT NULL DEFAULT 0,
  "reportedVia" TEXT,
  "reason" TEXT,
  "details" TEXT,
  "documentUrl" TEXT,
  "status" TEXT NOT NULL DEFAULT 'RECORDED',
  "decidedByUserId" TEXT,
  "decidedAt" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
