  "settlementAmount" INTEGER,
  "redoVisitId" TEXT,
  "correctiveTaskId" TEXT,
  "settledAt" TEXT,
  "settledByUserId" TEXT,
  "resolutionNote" TEXT,
  "clientToldAt" TEXT,
  "createdAt" TEXT NOT NULL,
