CREATE INDEX "Complaint_clientId_idx" ON "Complaint" ("clientId");
CREATE INDEX "Complaint_fileId_idx" ON "Complaint" ("fileId");
CREATE INDEX "Complaint_workerId_idx" ON "Complaint" ("workerId");

CREATE TABLE "PaymentDue" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "fileId" TEXT NOT NULL,
  "seq" INTEGER NOT NULL,
  "kind" TEXT NOT NULL,
  "periodStart" TEXT CHECK ("periodStart" IS NULL OR "periodStart" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "periodEnd" TEXT CHECK ("periodEnd" IS NULL OR "periodEnd" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "visitId" TEXT,
  "dueDate" TEXT NOT NULL CHECK ("dueDate" IS NULL OR "dueDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "plannedVisits" INTEGER,
  "expectedAmount" INTEGER NOT NULL,
  "invoiceId" TEXT,
  "amount" INTEGER NOT NULL,
  "paidAmount" INTEGER NOT NULL DEFAULT 0,
  "draftId" TEXT,
  "cancelledAt" TEXT,
  "cancelReason" TEXT,
  "note" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("fileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("visitId") REFERENCES "Visit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("invoiceId") REFERENCES "Invoice" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("draftId") REFERENCES "InvoiceDraft" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  UNIQUE ("fileId", "seq")
) STRICT;
CREATE INDEX "PaymentDue_dueDate_cancelledAt_idx" ON "PaymentDue" ("dueDate", "cancelledAt");
CREATE INDEX "PaymentDue_invoiceId_idx" ON "PaymentDue" ("invoiceId");
CREATE INDEX "PaymentDue_visitId_idx" ON "PaymentDue" ("visitId");
CREATE INDEX "PaymentDue_draftId_idx" ON "PaymentDue" ("draftId");
CREATE UNIQUE INDEX "PaymentDue_visit" ON "PaymentDue" ("visitId") WHERE "visitId" IS NOT NULL AND "cancelledAt" IS NULL;
CREATE UNIQUE INDEX "PaymentDue_period" ON "PaymentDue" ("fileId", "periodStart") WHERE "kind" = 'SCHEDULE' AND "cancelledAt" IS NULL;
CREATE UNIQUE INDEX "PaymentDue_single" ON "PaymentDue" ("fileId", "kind") WHERE "kind" IN ('SINGLE','INITIAL_JOB') AND "cancelledAt" IS NULL;
CREATE INDEX "PaymentDue_open" ON "PaymentDue" ("dueDate") WHERE "cancelledAt" IS NULL AND "paidAmount" < "amount";

CREATE TABLE "DueFollowUp" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "dueId" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "date" TEXT NOT NULL CHECK ("date" IS NULL OR "date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "note" TEXT,
  "promisedDate" TEXT CHECK ("promisedDate" IS NULL OR "promisedDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "createdAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  FOREIGN KEY ("dueId") REFERENCES "PaymentDue" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT
) STRICT;
CREATE INDEX "DueFollowUp_dueId_date_idx" ON "DueFollowUp" ("dueId", "date");

CREATE TABLE "InvoiceDraft" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "fileId" TEXT NOT NULL,
  "periodStart" TEXT CHECK ("periodStart" IS NULL OR "periodStart" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "periodEnd" TEXT CHECK ("periodEnd" IS NULL OR "periodEnd" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "replacesInvoiceId" TEXT,
  "payload" TEXT NOT NULL,
  "note" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("fileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("replacesInvoiceId") REFERENCES "Invoice" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT
) STRICT;
CREATE INDEX "InvoiceDraft_fileId_idx" ON "InvoiceDraft" ("fileId");

CREATE TABLE "Invoice" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "numberSeq" INTEGER NOT NULL,
  "numberYear" INTEGER NOT NULL,
  "number" TEXT NOT NULL,
  "fileId" TEXT NOT NULL,
  "clientId" TEXT NOT NULL,
  "division" TEXT NOT NULL,
  "serviceType" TEXT NOT NULL,
  "branchId" TEXT NOT NULL,
  "issueDate" TEXT NOT NULL CHECK ("issueDate" IS NULL OR "issueDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "issuedAt" TEXT NOT NULL,
  "issuedByUserId" TEXT NOT NULL,
  "periodStart" TEXT CHECK ("periodStart" IS NULL OR "periodStart" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "periodEnd" TEXT CHECK ("periodEnd" IS NULL OR "periodEnd" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "taxMode" TEXT NOT NULL,
  "vatRate" INTEGER NOT NULL,
  "pricesIncludeVat" INTEGER NOT NULL,
  "grossAmount" INTEGER NOT NULL,
  "discountAmount" INTEGER NOT NULL,
  "totalHT" INTEGER NOT NULL,
  "vatAmount" INTEGER NOT NULL,
  "totalTTC" INTEGER NOT NULL,
  "paymentMethod" TEXT NOT NULL,
  "stampDuty" INTEGER NOT NULL,
  "netToPay" INTEGER NOT NULL,
  "amountWordsAr" TEXT NOT NULL,
  "amountWordsFr" TEXT NOT NULL,
  "dueDate" TEXT NOT NULL CHECK ("dueDate" IS NULL OR "dueDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "paymentPlace" TEXT,
  "sellerSnapshot" TEXT NOT NULL,
  "buyerSnapshot" TEXT NOT NULL,
  "ifuMention" TEXT,
  "note" TEXT,
  "replacesInvoiceId" TEXT,
  "contentDigest" TEXT NOT NULL,
  "hashV" INTEGER NOT NULL,
  "chainSeq" INTEGER NOT NULL UNIQUE,
  "prevHash" TEXT NOT NULL,
  "hash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "createdByUserId" TEXT NOT NULL,
  FOREIGN KEY ("fileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("clientId") REFERENCES "Client" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("branchId") REFERENCES "Branch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("replacesInvoiceId") REFERENCES "Invoice" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("issuedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  UNIQUE ("numberYear", "numberSeq"),
  CHECK ("division" IN ('HOUSING','ORGANISATION','BUILDING','COMPLEX')),
  CHECK ("netToPay" = "totalTTC" + "stampDuty"),
  CHECK ("totalTTC" = "totalHT" + "vatAmount"),
  CHECK ("taxMode" <> 'IFU' OR ("vatAmount" = 0 AND "vatRate" = 0 AND "ifuMention" IS NOT NULL)),
  CHECK ("paymentMethod" = 'CASH' OR "stampDuty" = 0),
  CHECK ("grossAmount" - "discountAmount" = CASE WHEN "taxMode" = 'VAT' AND "pricesIncludeVat" = 0 THEN "totalHT" ELSE "totalTTC" END)
) STRICT;
CREATE INDEX "Invoice_fileId_idx" ON "Invoice" ("fileId");
CREATE INDEX "Invoice_clientId_idx" ON "Invoice" ("clientId");
CREATE INDEX "Invoice_issueDate_idx" ON "Invoice" ("issueDate");
CREATE INDEX "Invoice_division_issueDate_idx" ON "Invoice" ("division", "issueDate");

CREATE TABLE "InvoiceLine" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "invoiceId" TEXT NOT NULL,
  "seq" INTEGER NOT NULL,
  "kind" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "unitLabel" TEXT NOT NULL,
  "unitPrice" INTEGER NOT NULL,
  "amount" INTEGER NOT NULL,
  "dueId" TEXT,
  "visitId" TEXT,
  "complaintId" TEXT,
  "hashV" INTEGER NOT NULL,
  "chainSeq" INTEGER NOT NULL UNIQUE,
  "prevHash" TEXT NOT NULL,
  "hash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  FOREIGN KEY ("invoiceId") REFERENCES "Invoice" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("dueId") REFERENCES "PaymentDue" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("visitId") REFERENCES "Visit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("complaintId") REFERENCES "Complaint" ("id") ON DELETE RESTRICT,
  UNIQUE ("invoiceId", "seq")
) STRICT;
CREATE INDEX "InvoiceLine_visitId_idx" ON "InvoiceLine" ("visitId");
CREATE INDEX "InvoiceLine_complaintId_idx" ON "InvoiceLine" ("complaintId");

CREATE TABLE "InvoiceVisit" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "invoiceId" TEXT NOT NULL,
  "seq" INTEGER NOT NULL,
  "visitId" TEXT NOT NULL,
  "visitDate" TEXT NOT NULL CHECK ("visitDate" IS NULL OR "visitDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "dayName" TEXT NOT NULL,
  "arrival" TEXT CHECK ("arrival" IS NULL OR "arrival" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "departure" TEXT CHECK ("departure" IS NULL OR "departure" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "workersCount" INTEGER NOT NULL,
  "workedMin" INTEGER,
  "completion" TEXT NOT NULL,
  "signOff" TEXT,
  "signedBy" TEXT,
  "billable" INTEGER NOT NULL,
  "remark" TEXT,
  "hashV" INTEGER NOT NULL,
  "chainSeq" INTEGER NOT NULL UNIQUE,
  "prevHash" TEXT NOT NULL,
  "hash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  FOREIGN KEY ("invoiceId") REFERENCES "Invoice" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("visitId") REFERENCES "Visit" ("id") ON DELETE RESTRICT,
  UNIQUE ("invoiceId", "seq")
) STRICT;
CREATE INDEX "InvoiceVisit_visitId_idx" ON "InvoiceVisit" ("visitId");

CREATE TABLE "VisitBilling" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "visitId" TEXT NOT NULL UNIQUE,
  "billable" INTEGER NOT NULL,
  "reason" TEXT NOT NULL,
  "amount" INTEGER,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("visitId") REFERENCES "Visit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT
) STRICT;

CREATE TABLE "Payment" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "fileId" TEXT NOT NULL,
  "fileNumber" TEXT NOT NULL,
  "clientId" TEXT NOT NULL,
  "clientName" TEXT NOT NULL,
  "division" TEXT NOT NULL,
  "branchId" TEXT NOT NULL,
  "receivedDate" TEXT NOT NULL CHECK ("receivedDate" IS NULL OR "receivedDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "method" TEXT NOT NULL,
  "amount" INTEGER NOT NULL,
  "stampDuty" INTEGER NOT NULL,
  "totalReceived" INTEGER NOT NULL,
  "reference" TEXT,
  "payerName" TEXT NOT NULL,
  "place" TEXT,
  "collectorKind" TEXT NOT NULL,
  "collectorStaffId" TEXT,
  "receiptId" TEXT,
  "amountWordsAr" TEXT,
  "amountWordsFr" TEXT,
  "receiptReason" TEXT,
  "proofUrl" TEXT,
  "note" TEXT,
  "hashV" INTEGER NOT NULL,
  "enteredByUserId" TEXT NOT NULL,
  "enteredAt" TEXT NOT NULL,
  "chainSeq" INTEGER NOT NULL UNIQUE,
  "prevHash" TEXT NOT NULL,
  "hash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  FOREIGN KEY ("fileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("clientId") REFERENCES "Client" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("branchId") REFERENCES "Branch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("collectorStaffId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("receiptId") REFERENCES "Receipt" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("enteredByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK ("division" IN ('HOUSING','ORGANISATION','BUILDING','COMPLEX')),
  CHECK ("amount" >= 0 AND "totalReceived" = "amount" + "stampDuty"),
  CHECK (("method" = 'CASH') = ("receiptId" IS NOT NULL)),
  CHECK ("method" = 'CASH' OR "stampDuty" = 0),
  CHECK ("receiptId" IS NULL OR ("amountWordsAr" IS NOT NULL AND "amountWordsFr" IS NOT NULL AND "receiptReason" IS NOT NULL)),
  CHECK (("collectorKind" = 'OFFICE') = ("collectorStaffId" IS NULL))
) STRICT;
CREATE INDEX "Payment_fileId_idx" ON "Payment" ("fileId");
CREATE INDEX "Payment_clientId_idx" ON "Payment" ("clientId");
CREATE INDEX "Payment_division_receivedDate_idx" ON "Payment" ("division", "receivedDate");
CREATE INDEX "Payment_receivedDate_idx" ON "Payment" ("receivedDate");
CREATE UNIQUE INDEX "Payment_receipt" ON "Payment" ("receiptId") WHERE "receiptId" IS NOT NULL;

CREATE TABLE "PaymentAllocation" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "paymentId" TEXT NOT NULL,
  "dueId" TEXT NOT NULL,
  "amount" INTEGER NOT NULL,
  "reversesAllocationId" TEXT,
  "hashV" INTEGER NOT NULL,
  "chainSeq" INTEGER NOT NULL UNIQUE,
  "prevHash" TEXT NOT NULL,
  "hash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "createdByUserId" TEXT NOT NULL,
  FOREIGN KEY ("paymentId") REFERENCES "Payment" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("dueId") REFERENCES "PaymentDue" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("reversesAllocationId") REFERENCES "PaymentAllocation" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT
) STRICT;
CREATE INDEX "PaymentAllocation_dueId_idx" ON "PaymentAllocation" ("dueId");
CREATE INDEX "PaymentAllocation_paymentId_idx" ON "PaymentAllocation" ("paymentId");
CREATE UNIQUE INDEX "PaymentAllocation_one_reversal" ON "PaymentAllocation" ("reversesAllocationId") WHERE "reversesAllocationId" IS NOT NULL;

CREATE TABLE "Receipt" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "numberSeq" INTEGER NOT NULL,
  "numberYear" INTEGER NOT NULL,
  "number" TEXT NOT NULL,
  "issueDate" TEXT NOT NULL CHECK ("issueDate" IS NULL OR "issueDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "batchId" TEXT,
  "collectorKind" TEXT NOT NULL,
  "collectorStaffId" TEXT,
  "fileId" TEXT,
  "branchId" TEXT NOT NULL,
  "sellerSnapshot" TEXT NOT NULL,
  "hashV" INTEGER NOT NULL,
  "chainSeq" INTEGER NOT NULL UNIQUE,
  "prevHash" TEXT NOT NULL,
  "hash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "createdByUserId" TEXT NOT NULL,
  FOREIGN KEY ("batchId") REFERENCES "ReceiptBatch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("collectorStaffId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("fileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("branchId") REFERENCES "Branch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  UNIQUE ("numberYear", "numberSeq"),
  CHECK (("collectorKind" = 'OFFICE') = ("collectorStaffId" IS NULL))
) STRICT;
CREATE INDEX "Receipt_batchId_idx" ON "Receipt" ("batchId");
CREATE INDEX "Receipt_collectorStaffId_issueDate_idx" ON "Receipt" ("collectorStaffId", "issueDate");

CREATE TABLE "LegalEvent" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "invoiceId" TEXT,
  "paymentId" TEXT,
  "receiptId" TEXT,
  "type" TEXT NOT NULL,
  "reason" TEXT,
  "hashV" INTEGER NOT NULL,
  "chainSeq" INTEGER NOT NULL UNIQUE,
  "prevHash" TEXT NOT NULL,
  "hash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "createdByUserId" TEXT NOT NULL,
  FOREIGN KEY ("invoiceId") REFERENCES "Invoice" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("paymentId") REFERENCES "Payment" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("receiptId") REFERENCES "Receipt" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK (("invoiceId" IS NOT NULL) + ("paymentId" IS NOT NULL) + ("receiptId" IS NOT NULL) = 1),
  CHECK ("type" IN ('VOIDED','MISSING','PRINTED')),
  CHECK ("type" <> 'MISSING' OR "receiptId" IS NOT NULL),
  CHECK ("type" <> 'PRINTED' OR "paymentId" IS NULL),
  CHECK ("type" = 'PRINTED' OR "reason" IS NOT NULL)
) STRICT;
CREATE INDEX "LegalEvent_invoiceId_type_idx" ON "LegalEvent" ("invoiceId", "type");
CREATE INDEX "LegalEvent_paymentId_idx" ON "LegalEvent" ("paymentId");
CREATE INDEX "LegalEvent_receiptId_idx" ON "LegalEvent" ("receiptId");
CREATE UNIQUE INDEX "LegalEvent_invoice_void" ON "LegalEvent" ("invoiceId") WHERE "type" = 'VOIDED' AND "invoiceId" IS NOT NULL;
CREATE UNIQUE INDEX "LegalEvent_payment_void" ON "LegalEvent" ("paymentId") WHERE "type" = 'VOIDED' AND "paymentId" IS NOT NULL;
CREATE UNIQUE INDEX "LegalEvent_receipt_end" ON "LegalEvent" ("receiptId") WHERE "type" IN ('VOIDED','MISSING') AND "receiptId" IS NOT NULL;

CREATE TABLE "ReceiptBatch" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "date" TEXT NOT NULL CHECK ("date" IS NULL OR "date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "collectorKind" TEXT NOT NULL,
  "collectorStaffId" TEXT,
  "numberYear" INTEGER NOT NULL,
  "firstNumber" INTEGER NOT NULL,
  "lastNumber" INTEGER NOT NULL,
  "issuedByUserId" TEXT NOT NULL,
  "returnedAt" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  FOREIGN KEY ("collectorStaffId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("issuedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK (("collectorKind" = 'OFFICE') = ("collectorStaffId" IS NULL))
) STRICT;
CREATE INDEX "ReceiptBatch_date_idx" ON "ReceiptBatch" ("date");
CREATE INDEX "ReceiptBatch_returnedAt_idx" ON "ReceiptBatch" ("returnedAt");

CREATE TABLE "CashReconciliation" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "date" TEXT NOT NULL CHECK ("date" IS NULL OR "date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "collectorKind" TEXT NOT NULL,
  "collectorStaffId" TEXT,
  "receiptsIssued" INTEGER NOT NULL,
  "receiptsUsed" INTEGER NOT NULL,
  "receiptsVoided" INTEGER NOT NULL,
  "receiptsMissing" INTEGER NOT NULL,
  "expectedCash" INTEGER NOT NULL,
  "countedCash" INTEGER NOT NULL,
  "difference" INTEGER NOT NULL,
  "note" TEXT,
  "correctsReconciliationId" TEXT,
  "branchId" TEXT NOT NULL,
  "closedByUserId" TEXT NOT NULL,
  "closedAt" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  FOREIGN KEY ("collectorStaffId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("correctsReconciliationId") REFERENCES "CashReconciliation" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("branchId") REFERENCES "Branch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("closedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK (("collectorKind" = 'OFFICE') = ("collectorStaffId" IS NULL))
) STRICT;
CREATE INDEX "CashReconciliation_date_idx" ON "CashReconciliation" ("date");
CREATE INDEX "CashReconciliation_collectorStaffId_date_idx" ON "CashReconciliation" ("collectorStaffId", "date");
CREATE UNIQUE INDEX "CashReconciliation_day" ON "CashReconciliation" ("date", "collectorKind", COALESCE("collectorStaffId", ''), "branchId") WHERE "correctsReconciliationId" IS NULL;
CREATE UNIQUE INDEX "CashReconciliation_one_correction" ON "CashReconciliation" ("correctsReconciliationId") WHERE "correctsReconciliationId" IS NOT NULL;

CREATE TABLE "CashReconciliationLine" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "reconciliationId" TEXT NOT NULL,
  "receiptId" TEXT NOT NULL,
  "outcome" TEXT NOT NULL,
  "paymentId" TEXT,
  "createdAt" TEXT NOT NULL,
  FOREIGN KEY ("reconciliationId") REFERENCES "CashReconciliation" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("receiptId") REFERENCES "Receipt" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("paymentId") REFERENCES "Payment" ("id") ON DELETE RESTRICT,
  UNIQUE ("reconciliationId", "receiptId")
) STRICT;

CREATE TABLE "Expense" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "date" TEXT NOT NULL CHECK ("date" IS NULL OR "date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "division" TEXT NOT NULL,
  "category" TEXT NOT NULL,
  "amount" INTEGER NOT NULL,
  "method" TEXT,
  "paidTo" TEXT,
  "spentByEmployeeId" TEXT,
  "spentByName" TEXT,
  "fileId" TEXT,
  "supplierId" TEXT,
  "vehicleId" TEXT,
  "recurrence" TEXT NOT NULL DEFAULT 'NONE',
  "source" TEXT NOT NULL DEFAULT 'MANUAL',
  "purchaseId" TEXT,
  "maintenanceRecordId" TEXT,
  "staffPayoutId" TEXT,
  "payRunId" TEXT,
  "receiptUrl" TEXT,
  "note" TEXT,
  "branchId" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  "deletedAt" TEXT,
  "deleteReason" TEXT,
  FOREIGN KEY ("spentByEmployeeId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("fileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("supplierId") REFERENCES "Supplier" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("vehicleId") REFERENCES "Vehicle" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("purchaseId") REFERENCES "Purchase" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("maintenanceRecordId") REFERENCES "MaintenanceRecord" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("payRunId") REFERENCES "PayRun" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("branchId") REFERENCES "Branch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("staffPayoutId") REFERENCES "StaffPayout" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK (("source" = 'PURCHASE') = ("purchaseId" IS NOT NULL)),
  CHECK (("source" = 'MAINTENANCE') = ("maintenanceRecordId" IS NOT NULL)),
  CHECK (("source" = 'PAYROLL') = ("staffPayoutId" IS NOT NULL))
) STRICT;
CREATE INDEX "Expense_date_idx" ON "Expense" ("date");
CREATE INDEX "Expense_division_date_idx" ON "Expense" ("division", "date");
CREATE INDEX "Expense_category_date_idx" ON "Expense" ("category", "date");
CREATE INDEX "Expense_fileId_idx" ON "Expense" ("fileId");
CREATE INDEX "Expense_payRunId_idx" ON "Expense" ("payRunId");
CREATE UNIQUE INDEX "Expense_payout" ON "Expense" ("staffPayoutId", "category", "division") WHERE "staffPayoutId" IS NOT NULL AND "deletedAt" IS NULL;

CREATE TABLE "ExportBatch" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "kind" TEXT NOT NULL,
  "periodFrom" TEXT NOT NULL CHECK ("periodFrom" IS NULL OR "periodFrom" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "periodTo" TEXT NOT NULL CHECK ("periodTo" IS NULL OR "periodTo" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "format" TEXT NOT NULL,
  "fileName" TEXT NOT NULL,
  "rowCount" INTEGER NOT NULL,
  "fileHash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "createdByUserId" TEXT NOT NULL,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT
) STRICT;
CREATE INDEX "ExportBatch_kind_periodFrom_idx" ON "ExportBatch" ("kind", "periodFrom");

CREATE TABLE "StockItem" (
