CREATE INDEX "StockItem_kind_isActive_idx" ON "StockItem" ("kind", "isActive");
CREATE INDEX "StockItem_low" ON "StockItem" ("id") WHERE "isActive" = 1 AND "minLevel" IS NOT NULL AND "onHandQty" <= "minLevel";

CREATE TABLE "EquipmentUnit" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "itemId" TEXT NOT NULL,
  "numberSeq" INTEGER NOT NULL UNIQUE,
  "number" TEXT NOT NULL UNIQUE,
  "serialNumber" TEXT,
  "brand" TEXT,
  "model" TEXT,
  "purchaseDate" TEXT CHECK ("purchaseDate" IS NULL OR "purchaseDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "purchaseCost" INTEGER,
  "supplierId" TEXT,
  "condition" TEXT NOT NULL,
  "locationKind" TEXT NOT NULL,
  "locationWorkerId" TEXT,
  "locationFileId" TEXT,
  "locationSiteId" TEXT,
  "maintenanceIntervalDays" INTEGER,
  "lastMaintenanceDate" TEXT CHECK ("lastMaintenanceDate" IS NULL OR "lastMaintenanceDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "nextMaintenanceDate" TEXT CHECK ("nextMaintenanceDate" IS NULL OR "nextMaintenanceDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "retiredAt" TEXT,
  "retireReason" TEXT,
  "photoUrl" TEXT,
  "branchId" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("itemId") REFERENCES "StockItem" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("supplierId") REFERENCES "Supplier" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("locationWorkerId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("locationFileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("locationSiteId") REFERENCES "Site" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("branchId") REFERENCES "Branch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT
) STRICT;
CREATE INDEX "EquipmentUnit_itemId_idx" ON "EquipmentUnit" ("itemId");
CREATE INDEX "EquipmentUnit_nextMaintenanceDate_idx" ON "EquipmentUnit" ("nextMaintenanceDate");
CREATE INDEX "EquipmentUnit_condition_idx" ON "EquipmentUnit" ("condition");
CREATE INDEX "EquipmentUnit_locationKind_locationFileId_idx" ON "EquipmentUnit" ("locationKind", "locationFileId");
CREATE INDEX "EquipmentUnit_locationKind_locationSiteId_idx" ON "EquipmentUnit" ("locationKind", "locationSiteId");

CREATE TABLE "StockMovement" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "itemId" TEXT NOT NULL,
  "unitId" TEXT,
  "type" TEXT NOT NULL,
  "qty" INTEGER NOT NULL,
  "unitCost" INTEGER NOT NULL,
  "date" TEXT NOT NULL CHECK ("date" IS NULL OR "date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "handOutLineId" TEXT,
  "handOutReturnId" TEXT,
  "purchaseLineId" TEXT,
  "countLineId" TEXT,
  "reversesMovementId" TEXT,
  "reason" TEXT,
  "branchId" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "createdByUserId" TEXT NOT NULL,
  FOREIGN KEY ("itemId") REFERENCES "StockItem" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("unitId") REFERENCES "EquipmentUnit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("handOutLineId") REFERENCES "HandOutLine" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("handOutReturnId") REFERENCES "HandOutReturn" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("purchaseLineId") REFERENCES "PurchaseLine" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("countLineId") REFERENCES "InventoryCountLine" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("reversesMovementId") REFERENCES "StockMovement" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("branchId") REFERENCES "Branch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK (("handOutLineId" IS NOT NULL) + ("handOutReturnId" IS NOT NULL) + ("purchaseLineId" IS NOT NULL) + ("countLineId" IS NOT NULL) <= 1)
) STRICT;
CREATE INDEX "StockMovement_itemId_date_idx" ON "StockMovement" ("itemId", "date");
CREATE INDEX "StockMovement_unitId_idx" ON "StockMovement" ("unitId");
CREATE INDEX "StockMovement_handOutLineId_idx" ON "StockMovement" ("handOutLineId");
CREATE UNIQUE INDEX "StockMovement_one_reversal" ON "StockMovement" ("reversesMovementId") WHERE "reversesMovementId" IS NOT NULL;

