CREATE TABLE "HandOut" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "numberSeq" INTEGER NOT NULL,
  "numberYear" INTEGER NOT NULL,
  "number" TEXT NOT NULL,
  "date" TEXT NOT NULL CHECK ("date" IS NULL OR "date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "purpose" TEXT NOT NULL DEFAULT 'JOB',
  "fileId" TEXT,
  "visitId" TEXT,
  "serviceType" TEXT,
  "division" TEXT,
  "workerId" TEXT NOT NULL,
  "handedByUserId" TEXT NOT NULL,
  "note" TEXT,
  "cancelledAt" TEXT,
  "cancelledByUserId" TEXT,
  "cancelReason" TEXT,
  "branchId" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("fileId") REFERENCES "File" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("visitId") REFERENCES "Visit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("workerId") REFERENCES "StaffMember" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("branchId") REFERENCES "Branch" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("handedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("cancelledByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  UNIQUE ("numberYear", "numberSeq"),
  CHECK (("purpose" = 'JOB') = ("fileId" IS NOT NULL))
) STRICT;
CREATE INDEX "HandOut_fileId_idx" ON "HandOut" ("fileId");
CREATE INDEX "HandOut_visitId_idx" ON "HandOut" ("visitId");
CREATE INDEX "HandOut_workerId_date_idx" ON "HandOut" ("workerId", "date");
CREATE INDEX "HandOut_division_serviceType_date_idx" ON "HandOut" ("division", "serviceType", "date");

CREATE TABLE "HandOutLine" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "handOutId" TEXT NOT NULL,
  "itemId" TEXT NOT NULL,
  "unitId" TEXT,
  "qty" INTEGER NOT NULL,
  "condition" TEXT,
  "unitCost" INTEGER NOT NULL,
  "expectReturn" INTEGER NOT NULL,
  "stayAtSite" INTEGER NOT NULL DEFAULT 0,
