CREATE INDEX "HandOutLine_handOutId_idx" ON "HandOutLine" ("handOutId");
CREATE INDEX "HandOutLine_itemId_idx" ON "HandOutLine" ("itemId");
CREATE INDEX "HandOutLine_unitId_idx" ON "HandOutLine" ("unitId");

CREATE TABLE "HandOutReturn" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "handOutLineId" TEXT NOT NULL,
