CREATE INDEX "Purchase_date_idx" ON "Purchase" ("date");
CREATE INDEX "Purchase_supplierId_idx" ON "Purchase" ("supplierId");

CREATE TABLE "PurchaseLine" (
  "id" TEXT PRIMARY KEY NOT NULL,
