CREATE TABLE "MaintenanceRecord" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "unitId" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "date" TEXT NOT NULL CHECK ("date" IS NULL OR "date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "description" TEXT NOT NULL,
  "cost" INTEGER NOT NULL DEFAULT 0,
  "provider" TEXT,
  "conditionAfter" TEXT NOT NULL,
  "nextDueDate" TEXT CHECK ("nextDueDate" IS NULL OR "nextDueDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("unitId") REFERENCES "EquipmentUnit" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT
) STRICT;
CREATE INDEX "MaintenanceRecord_unitId_date_idx" ON "MaintenanceRecord" ("unitId", "date");

-- ── template triggers ──

CREATE TRIGGER "Branch_no_delete" BEFORE DELETE ON "Branch"
BEGIN SELECT RAISE(ABORT, 'NO_DELETE:Branch'); END;

CREATE TRIGGER "User_no_delete" BEFORE DELETE ON "User"
